            previousInt = a1.get(i);
            assertEquals(previousInt, a2.get(i));
        }
    }
    if (context.getExecutorState().getFailureCause() != null) {
        throw context.getExecutorState().getFailureCause();
    }
    assertTrue(!context.getExecutorState().isFailed());
